<?php require __DIR__.'/includes/bootstrap.php';$slug=trim($_GET['slug']??'');$rows=[];$title='Comments';if($pdo&&$slug){$s=$pdo->prepare("SELECT a.title,c.name,c.body,c.created_at FROM comments c JOIN articles a ON a.id=c.article_id WHERE a.slug=? AND a.status='approved' ORDER BY c.created_at DESC");$s->execute([$slug]);$rows=$s->fetchAll();$title=$s->fetchColumn()?:$title;}require __DIR__.'/includes/header.php';?><div class="container"><h1>Comments</h1><?php foreach($rows as $r):?><article class="card"><p><?=nl2br(e($r['body']))?></p><p class="muted">By <?=e($r['name'])?> · <?=e($r['created_at'])?></p></article><?php endforeach;if(!$rows):?><p class="muted">No approved comments.</p><?php endif;?></div><?php require __DIR__.'/includes/footer.php';
